// iosrt sample: a storyboard app. Info.plist names UIMainStoryboardFile =
// Main; Main.storyboardc (generated by tools/mknib.py --storyboard, in
// ibtool's layout) holds a navigation controller whose root is
// ListController. Its view embeds BadgeController through an embed segue,
// and its button runs a show segue to DetailController.
#import <UIKit/UIKit.h>

@interface DetailController : UIViewController
@property (nonatomic, strong) UILabel *label;
@property (nonatomic, copy) NSString *item;
@end
@implementation DetailController
- (void)viewDidLoad {
    [super viewDidLoad];
    NSLog(@"detail viewDidLoad: label '%@', item '%@', has storyboard %d, nav stack %lu",
          self.label.text, self.item, self.storyboard != nil, (unsigned long)self.navigationController.viewControllers.count);
}
@end

@interface BadgeController : UIViewController
@end
@implementation BadgeController
- (void)viewDidLoad { [super viewDidLoad]; NSLog(@"badge viewDidLoad: frame %@", NSStringFromCGRect(self.view.frame)); }
@end

@interface ListController : UIViewController
@end
@implementation ListController
- (void)viewDidLoad {
    [super viewDidLoad];
    UIViewController *child = self.childViewControllers.firstObject;
    NSLog(@"list viewDidLoad: title '%@', %lu child (%@) in container %@", self.navigationItem.title, (unsigned long)self.childViewControllers.count,
          NSStringFromClass([child class]), NSStringFromCGRect(child.view.superview.frame));
}
- (void)prepareForSegue:(UIStoryboardSegue *)segue sender:(id)sender {
    NSLog(@"prepareForSegue '%@': %@ -> %@ (sender %@)", segue.identifier, NSStringFromClass([segue.sourceViewController class]),
          NSStringFromClass([segue.destinationViewController class]), NSStringFromClass([sender class]));
    if ([segue.destinationViewController isKindOfClass:[DetailController class]]) ((DetailController *)segue.destinationViewController).item = @"Row 1";
}
@end

@interface SBAppDelegate : UIResponder <UIApplicationDelegate>
@property (nonatomic, strong) UIWindow *window;
@end
@implementation SBAppDelegate
- (BOOL)application:(UIApplication *)app didFinishLaunchingWithOptions:(NSDictionary *)opts {
    UINavigationController *nav = (UINavigationController *)self.window.rootViewController;
    NSLog(@"launch: window made by UIKit %d, root %@ with top %@", self.window != nil, NSStringFromClass([nav class]), NSStringFromClass([nav.topViewController class]));
    UIViewController *made = [nav.storyboard instantiateViewControllerWithIdentifier:@"DetailController"];
    NSLog(@"instantiated by identifier: %@", NSStringFromClass([made class]));
    return YES;
}
@end

int main(int argc, char *argv[]) {
    @autoreleasepool { return UIApplicationMain(argc, argv, nil, NSStringFromClass([SBAppDelegate class])); }
}
